/* Same interface for the browser prototype and the packaged Android app. */
(function(){'use strict';const native=window.NotaAndroid,pending=new Map();
window.addEventListener('nota-ai',e=>{const d=e.detail,job=pending.get(d?.id);if(!job)return;if(d.event==='progress'){job.progress?.(d.message);return;}pending.delete(d.id);clearTimeout(job.timer);job.cleanup?.();if(d.error){const error=Object.assign(Error(d.message||'Assistance is unavailable.'),{code:d.error==='CANCELLED'?'CANCELLED':d.error,retryAt:d.retryAt});if(d.error==='CANCELLED')error.name='AbortError';job.reject(error);}else job.resolve(d);});
function localRequest(action,input={},options={}){if(!native?.requestAI)return Promise.reject(Object.assign(Error('Local AI is available in the Android app on supported phones.'),{code:'UNAVAILABLE'}));return new Promise((resolve,reject)=>{const id=crypto.randomUUID();const stop=()=>{native.cancelAI(id);pending.delete(id);clearTimeout(job.timer);options.signal?.removeEventListener('abort',stop);reject(new DOMException('Request cancelled','AbortError'));};const job={resolve,reject,progress:options.onProgress,cleanup:()=>options.signal?.removeEventListener('abort',stop),timer:setTimeout(()=>{native.cancelAI(id);pending.delete(id);job.cleanup();reject(Object.assign(Error('The assistant took too long to prepare. Try again after the download finishes.'),{code:'TIMEOUT'}));},action==='generate'?660000:action==='cloud'?115000:35000)};if(options.signal?.aborted){clearTimeout(job.timer);reject(new DOMException('Request cancelled','AbortError'));return;}pending.set(id,job);options.signal?.addEventListener('abort',stop,{once:true});try{if(action==='cloud')native.requestCloudAI(id,JSON.stringify(input));else native.requestAI(id,action,JSON.stringify(input));}catch(e){pending.delete(id);clearTimeout(job.timer);job.cleanup();reject(Object.assign(Error('Update the Android app to connect local assistance.'),{code:'UNAVAILABLE'}));}});}

function cloudState(){try{return JSON.parse(native?.getCloudAIState?.()||'{}');}catch{return {};}}
window.NotaPlatform={cloudState,allowCloud:allowed=>native?.allowCloudAI?.(!!allowed),cloudRequest:(input,options)=>localRequest('cloud',input,options),isAndroid:!!native,hasLocalAI:!!native?.requestAI,localRequest,
 appearance(theme){if(native?.setTheme)native.setTheme(theme);else native?.setAppearance?.(theme==='dark');},
 read(text,rate){if(!native)return false;native.speak(String(text),Number(rate)||1);return true;},
 stopRead(){native?.stopSpeaking();window.speechSynthesis?.cancel();},
 syncReminders(items){if(!native)return;native.syncReminders(JSON.stringify(items.filter(n=>!n.deletedAt&&n.reminder).map(n=>({id:n.id,...n.reminder}))));},
 mergeNativeReminders(items){if(!native)return;try{const saved=JSON.parse(native.getReminders());for(const n of items){const r=saved.find(r=>r.id===n.id);if(r&&n.reminder&&(n.reminder.when===r.sourceWhen||n.reminder.when===r.when)){n.reminder.when=r.when;n.reminder.fired=r.fired;}}}catch{}},
 alerts(){native?.requestNotifications();},
 async exportBlob(blob,name){if(!native)return false;const id=native.beginExport(String(name),blob.type||'application/octet-stream',blob.size);if(!id)throw Error('Another file is being saved. Finish that export first.');try{for(let offset=0;offset<blob.size;offset+=192*1024){const bytes=new Uint8Array(await blob.slice(offset,offset+192*1024).arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));if(!native.appendExport(id,btoa(binary)))throw Error('Could not prepare the file.');}if(!native.finishExport(id))throw Error('Export size did not match.');return true;}catch(e){native.cancelExport(id);throw e;}}
};
})();
